 Spacer(Modifier.height(2.dp))

 Text(
 "닉네임은 최소 2자, 최대 12자까지 가능해요",
 style = TraceTheme.typography.bodyXSM.copy(fontSize = 12.sp),
 color = Red,
 modifier = Modifier
 .align(Alignment.Start)
 .padding(top = 10.dp, start = 20.dp)
 )
 }

 Spacer(Modifier.weight(1f))

 Button(
 onClick = {
 if (signUpAvailability) registerUser()
 },
 colors = if (!signUpAvailability) ButtonDefaults.buttonColors(
 PrimaryDefault
 .copy(alpha = 0.65F)
 ) else ButtonDefaults.buttonColors(
 PrimaryActive
 ),
 shape = RoundedCornerShape(8.dp),
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 20.dp)
 ) {
 Text(
 "완료",
 color = White,
 style = TraceTheme.typography.bodyXMM
 )
 }

 Spacer(modifier = Modifier.height(60.dp))
 }
}

@Composable
private fun ProfileImage(imageUrl: String?) {
 val profileImage = rememberAsyncImagePainter(imageUrl ?: R.drawable.default_profile)
 val imageSize = if (imageUrl != null) 129.dp else 115.dp
 val paddingValue = if (imageUrl != null) 2.dp else 9.dp

 Box(Modifier.padding(paddingValue)) {
 Image(
 painter = profileImage,
 contentDescription = "프로필 이미지",
 modifier = Modifier
 .size(imageSize)
 .clip(CircleShape),
 contentScale = ContentScale.Crop
 )
 }
}


"},{"role":"assistant","content":[{"type":"text","text":"## BackButton 사용 현황 분석

### ✅ **BackButton 컴포넌트를 사용하는 화면들**
1. `UserProfileScreen` - ✅ BackButton 사용
2. `SettingScreen` - ✅ BackButton 사용 
3. `UpdateProfileScreen` - ✅ BackButton 사용
4. `SearchScreen` - ✅ BackButton 사용
5. `SwallowScreen` - ✅ BackButton 사용
6. `PostScreen` - ✅ BackButton 사용
7. `BlockedUserScreen` - ✅ BackButton 사용

### ❌ **BackButton을 사용하지 않고 직접 구현한 화면들**

#### 1. **NotificationScreen**
```kotlin
// 현재 구현 (직접 구현)
IconButton(
 onClick = { navigateBack() },
 modifier = Modifier.padding(start = 10.dp, top = 2.dp)
) {
 Icon(
 painter = painterResource(R.drawable.arrow_left_ic),
 contentDescription = "뒤로가기",
 modifier = Modifier.size(36.dp), // ❌ 크기가 다름 (36dp vs 24dp)
 )
}
```

#### 2. **WritePostScreen**
```kotlin
// 현재 구현 (직접 구현)
Icon(
 painter = painterResource(R.drawable.arrow_left_ic),
 contentDescription = "뒤로 가기",
 modifier = Modifier
 .size(32.dp) // ❌ 크기가 다름
 .clickable(isRipple = true) { navigateBack() }
)
```

#### 3. **EditProfileScreen**
```kotlin
// 현재 구현 (직접 구현)
Icon(
 painter = painterResource(R.drawable.arrow_left_ic),
 contentDescription = "뒤로 가기",
 modifier = Modifier
 .size(50.dp) // ❌ 크기가 다름
 .align(Alignment.Start)
 .padding(8.dp)
 .clickable(isRipple = true) { navigateBack() }
)
```

#### 4. **UpdatePostScreen & VerifyMissionScreen**
- `close_ic` 사용 (X 아이콘)

## **일관성 문제점**

1. **아이콘 크기 불일치**: 24dp, 32dp, 36dp, 50dp 등 다양함
2. **패딩 불일치**: 각 화면마다 다른 패딩 적용
3. **컴포넌트 불일치**: BackButton vs 직접 구현
4. **아이콘 타입 불일치**: arrow_left_ic vs close_ic

## **권장사항**

모든 화면에서 **BackButton 컴포넌트를 통일**해서 사용하는 것이 좋겠습니다:

```kotlin
// 통일된 사용법
BackButton(navigateBack)
```

이렇게 하면 일관된 디자인과 UX를 제공할 수 있고, 향후 수정사항이 있을 때 한 곳에서만 관리하면 됩니다."}]}]},"5b2667cd-adfd-4690-9e85-eae4511e194f":{"id":"5b2667cd-adfd-4690-9e85-eae4511e194f","name":"```","timestamp":1760597662704,"messages":[{"role":"user","content":[{"type":"text","text":"<rules_context>

