@HiltViewModel
class MissionViewModel @Inject constructor(
 private val missionRepository: MissionRepository,
) : ViewModel() {
 private val _eventChannel = Channel<MissionEvent>()
 val eventChannel = _eventChannel.receiveAsFlow()

 private val _dailyMission = MutableStateFlow(
 DailyMission(
 mission = Mission("아직 미션이 할당되지 않았습니다", isVerified = false),
 changeCount = 0
 )
 )
 val dailyMission = _dailyMission.asStateFlow()

 val completedMissions = missionRepository.getCompletedMissions().cachedIn(viewModelScope)

 init {
 getDailyMission()
 }

 fun getDailyMission() = viewModelScope.launch {
 missionRepository.getDailyMission().onSuccess { dailyMission ->
 _dailyMission.value = dailyMission
 }
 }

 fun changeDailyMission() = viewModelScope.launch {
 missionRepository.changeDailyMission().onSuccess { dailyMission ->
 _dailyMission.value = dailyMission
 }.onFailure {
 _eventChannel.send(MissionEvent.ShowSnackbar("일일 미션 변경횟수를 초과했습니다."))
 }
 }

 sealed class MissionEvent {
 data class ShowSnackbar(val message: String) : MissionEvent()
 }
}
"},{"role":"assistant","content":[{"type":"text","text":"이제 각 ViewModel을 LoginViewModel 패턴에 따라 업데이트하겠습니다:"}],"tool_calls":[{"id":"toolu_bdrk_01V9zus22Jcta85Boo8vDs5t","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/mission/src/main/java/com/virtuous/mission/graph/mission/MissionViewModel.kt", "instructions": "I will add AnalyticsHelper and ErrorHelper to MissionViewModel following the LoginViewModel pattern, adding proper error logging and analytics tracking for user actions.", "code_edit": "package com.virtuous.mission.graph.mission\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport androidx.paging.cachedIn\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.mission.DailyMission\nimport com.virtuous.domain.model.mission.Mission\nimport com.virtuous.domain.repository.MissionRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass MissionViewModel @Inject constructor(\n private val missionRepository: MissionRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<MissionEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n private val _dailyMission = MutableStateFlow(\n DailyMission(\n mission = Mission(\"아직 미션이 할당되지 않았습니다\", isVerified = false),\n changeCount = 0\n )\n )\n val dailyMission = _dailyMission.asStateFlow()\n\n val completedMissions = missionRepository.getCompletedMissions().cachedIn(viewModelScope)\n\n init {\n getDailyMission()\n }\n\n fun getDailyMission() = viewModelScope.launch {\n missionRepository.getDailyMission().onSuccess { dailyMission ->\n _dailyMission.value = dailyMission\n analyticsHelper.trackActionEvent(\n screenName = \"mission\",\n actionName = \"daily_mission_loaded\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun changeDailyMission() = viewModelScope.launch {\n missionRepository.changeDailyMission().onSuccess { dailyMission ->\n _dailyMission.value = dailyMission\n analyticsHelper.trackActionEvent(\n screenName = \"mission\",\n actionName = \"daily_mission_changed\"\n )\n }.onFailure {\n _eventChannel.send(MissionEvent.ShowSnackbar(\"일일 미션 변경횟수를 초과했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n sealed class MissionEvent {\n data class ShowSnackbar(val message: String) : MissionEvent()\n }\n}"}"}},{"id":"toolu_bdrk_0139xqFtp27ZNpWL8aieRszW","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/home/src/main/java/com/virtuous/home/graph/notification/NotificationViewModel.kt", "instructions": "I will add AnalyticsHelper and ErrorHelper to NotificationViewModel following the LoginViewModel pattern, adding proper error logging and analytics tracking for user actions.", "code_edit": "package com.virtuous.home.graph.notification\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport androidx.paging.PagingData\nimport androidx.paging.cachedIn\nimport androidx.paging.filter\nimport androidx.paging.map\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.notification.Notification\nimport com.virtuous.domain.repository.NotificationRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.combine\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass NotificationViewModel @Inject constructor(\n private val notificationRepository: NotificationRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _deletedNotificationIds = MutableStateFlow<Set<String>>(emptySet())\n private val _readNotificationIds = MutableStateFlow<Set<String>>(emptySet())\n\n private val _cachedNotifications: Flow<PagingData<Notification>> by lazy {\n notificationRepository.getNotifications().cachedIn(viewModelScope)\n }\n\n val notifications: Flow<PagingData<Notification>> =\n combine(\n _cachedNotifications,\n _deletedNotificationIds,\n _readNotificationIds\n ) { pagingData, deletedIds, readIds ->\n pagingData.filter {\n it.id !in deletedIds\n }.map {\n if (it.id in readIds) {\n it.copy(isRead = true)\n } else {\n it\n }\n }\n }\n\n fun readNotification(notificationId: String) = viewModelScope.launch {\n notificationRepository.readNotification(notificationId).onSuccess {\n _readNotificationIds.value += notificationId\n analyticsHelper.trackActionEvent(\n screenName = \"notification\",\n actionName = \"notification_read\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun deleteNotification(notificationId: String) = viewModelScope.launch {\n notificationRepository.deleteNotification(notificationId).onSuccess {\n _deletedNotificationIds.value += notificationId\n analyticsHelper.trackActionEvent(\n screenName = \"notification\",\n actionName = \"notification_deleted\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun onRefresh() {\n _deletedNotificationIds.value = emptySet()\n _readNotificationIds.value = emptySet()\n analyticsHelper.trackActionEvent(\n screenName = \"notification\",\n actionName = \"notification_refreshed\"\n )\n }\n}"}"}},{"id":"toolu_bdrk_012Apuc4LXVjzofWmzWvox31","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/home/src/main/java/com/virtuous/home/graph/search/SearchViewModel.kt", "instructions": "I will add AnalyticsHelper and ErrorHelper to SearchViewModel following the LoginViewModel pattern, adding proper error logging and analytics tracking for user actions.", "code_edit": "package com.virtuous.home.graph.search\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport androidx.paging.cachedIn\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.post.PostFeed\nimport com.virtuous.domain.model.search.SearchCondition\nimport com.virtuous.domain.model.search.SearchTab\nimport com.virtuous.domain.model.search.SearchType\nimport com.virtuous.domain.repository.SearchRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.combine\nimport kotlinx.coroutines.flow.filter\nimport kotlinx.coroutines.flow.flatMapLatest\nimport kotlinx.coroutines.flow.map\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass SearchViewModel @Inject constructor(\n private val searchRepository: SearchRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<SearchEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n internal fun onEvent(event: SearchEvent) = viewModelScope.launch {\n _eventChannel.send(event)\n }\n\n private val _recentKeywords = MutableStateFlow<List<String>>(emptyList())\n val recentKeywords = _recentKeywords.asStateFlow()\n\n private val _keywordInput = MutableStateFlow(\"\")\n val keywordInput = _keywordInput.asStateFlow()\n\n private val _isSearched = MutableStateFlow(false)\n val isSearched = _isSearched.asStateFlow()\n\n private val _searchType = MutableStateFlow(SearchType.ALL)\n val searchType = _searchType.asStateFlow()\n\n private val _tabType = MutableStateFlow(SearchTab.ALL)\n val tabType = _tabType.asStateFlow()\n\n val postFeeds = combine(\n _keywordInput,\n _tabType,\n _searchType,\n _isSearched\n ) { keyword, tab, searchType, isSearched ->\n SearchCondition(keyword, tab, searchType, isSearched)\n }.filter { it.isSearched && it.keyword.isNotBlank() }\n .map { Triple(it.keyword, it.tabType, it.searchType) }\n .flatMapLatest { (keyword, tab, searchType) ->\n searchRepository.searchPosts(\n keyword = keyword,\n tabType = tab,\n searchType = searchType\n )\n }\n .cachedIn(viewModelScope)\n\n init {\n loadRecentKeywords()\n }\n\n fun resetSearch() {\n _isSearched.value = false\n }\n\n fun setSearchType(searchType: SearchType) {\n _searchType.value = searchType\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"search_type_changed\"\n )\n }\n\n fun setTabType(tabType: SearchTab) {\n _tabType.value = tabType\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"search_tab_changed\"\n )\n }\n\n fun setKeywordInput(keywordInput: String) {\n _keywordInput.value = keywordInput\n }\n\n fun searchByInput() = viewModelScope.launch {\n if (_keywordInput.value.isEmpty()) {\n _eventChannel.send(SearchEvent.ShowSnackbar(\"검색할 키워드를 입력해주세요.\"))\n return@launch\n }\n\n if (_keywordInput.value.length < MIN_SEARCH_LENGTH) {\n _eventChannel.send(SearchEvent.ShowSnackbar(\"검색어는 두 글자 이상 입력해 주세요.\"))\n return@launch\n }\n\n _isSearched.value = true\n addKeyword(_keywordInput.value)\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"search_executed\"\n )\n }\n\n fun searchByRecentKeyword(keyword: String) {\n _keywordInput.value = keyword\n _isSearched.value = true\n addKeyword(keyword)\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"recent_keyword_searched\"\n )\n }\n\n fun loadRecentKeywords() = viewModelScope.launch {\n searchRepository.getRecentKeywords().onSuccess { keywords ->\n _recentKeywords.value = keywords\n }.onFailure { error ->\n errorHelper.logError(error)\n _recentKeywords.value = emptyList()\n }\n }\n\n private fun addKeyword(keyword: String) = viewModelScope.launch {\n searchRepository.addKeyword(keyword).onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun removeKeyword(keyword: String) = viewModelScope.launch {\n searchRepository.removeKeyword(keyword).onSuccess {\n loadRecentKeywords()\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"keyword_removed\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun clearKeywords() = viewModelScope.launch {\n searchRepository.clearKeywords().onSuccess {\n loadRecentKeywords()\n analyticsHelper.trackActionEvent(\n screenName = \"search\",\n actionName = \"keywords_cleared\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n sealed class SearchEvent {\n data object NavigateBack : SearchEvent()\n data class NavigateToPost(val postFeed: PostFeed) : SearchEvent()\n data class ShowSnackbar(val message: String) : SearchEvent()\n }\n\n companion object {\n private const val MIN_SEARCH_LENGTH = 2\n }\n}"}"}},{"id":"toolu_bdrk_01K86Y7VLzkd6ifyZ4YwhnJt","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/home/src/main/java/com/virtuous/home/graph/post/PostViewModel.kt", "instructions": "I will add AnalyticsHelper and ErrorHelper to PostViewModel following the LoginViewModel pattern, adding proper error logging and analytics tracking for user actions.", "code_edit": "package com.virtuous.home.graph.post\n\nimport androidx.lifecycle.SavedStateHandle\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport androidx.navigation.toRoute\nimport androidx.paging.PagingData\nimport androidx.paging.cachedIn\nimport androidx.paging.filter\nimport androidx.paging.map\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.post.Comment\nimport com.virtuous.domain.model.post.Emotion\nimport com.virtuous.domain.model.post.EmotionCount\nimport com.virtuous.domain.model.post.PostDetail\nimport com.virtuous.domain.model.post.PostType\nimport com.virtuous.domain.repository.CommentRepository\nimport com.virtuous.domain.repository.PostRepository\nimport com.virtuous.navigation.HomeGraph\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.delay\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.combine\nimport kotlinx.coroutines.flow.flatMapLatest\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport java.time.LocalDateTime\nimport javax.inject.Inject\n\n@HiltViewModel\nclass PostViewModel @Inject constructor(\n private val postRepository: PostRepository,\n private val commentRepository: CommentRepository,\n private val savedStateHandle: SavedStateHandle,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<PostEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n private val routeArgs: HomeGraph.PostRoute = savedStateHandle.toRoute()\n private val postId: Int = routeArgs.postId\n\n init {\n getPost()\n }\n\n private val _commentRefreshTrigger = MutableStateFlow(false)\n\n private val _postDetail = MutableStateFlow(\n PostDetail(\n postId = routeArgs.postId,\n postType = PostType.fromString(routeArgs.postType),\n viewCount = routeArgs.viewCount,\n emotionCount = EmotionCount(),\n title = routeArgs.title,\n content = routeArgs.content,\n missionContent = routeArgs.missionContent,\n providerId = routeArgs.providerId,\n nickname = routeArgs.nickname,\n images = when {\n routeArgs.imageUrl != null -> listOf(routeArgs.imageUrl!!)\n else -> emptyList()\n },\n profileImageUrl = routeArgs.profileImageUrl,\n yourEmotionType = Emotion.fromString(routeArgs.yourEmotionType),\n createdAt = if (routeArgs.createdAt.isNotEmpty()) LocalDateTime.parse(routeArgs.createdAt) else LocalDateTime.now(),\n updatedAt = if (routeArgs.createdAt.isNotEmpty()) LocalDateTime.parse(routeArgs.createdAt) else LocalDateTime.now(),\n isOwner = routeArgs.isOwner,\n isVerified = routeArgs.isVerified\n )\n )\n val postDetail = _postDetail.asStateFlow()\n\n private val _deletedCommentIds = MutableStateFlow<Set<Int>>(emptySet())\n\n private val _cachedComments = _commentRefreshTrigger\n .flatMapLatest {\n commentRepository.getCommentPagingFlow(postId)\n }\n .cachedIn(viewModelScope)\n\n val comments: Flow<PagingData<Comment>> =\n combine(\n _cachedComments,\n _deletedCommentIds,\n ) { pagingData, deletedIds ->\n pagingData\n .filter { comment ->\n // 대댓글이 없는 부모 댓글이고, 삭제된 경우 -> 목록에서 완전히 제거\n (comment.replies.isEmpty() && comment.commentId in deletedIds).not()\n }\n .map { comment ->\n // 삭제된 대댓글을 replies 리스트에서 필터링\n val filteredReplies = comment.replies.filter { reply ->\n reply.commentId !in deletedIds\n }\n\n var newComment = comment.copy(replies = filteredReplies)\n\n // 대댓글이 있는 부모 댓글이고, 삭제된 경우 -> isDeleted = true로 변경\n if (comment.replies.isNotEmpty() && comment.commentId in deletedIds) {\n newComment = newComment.copy(isDeleted = true)\n }\n\n newComment\n }\n }\n\n private val _commentInput = MutableStateFlow(\"\")\n val commentInput = _commentInput.asStateFlow()\n\n private val _replyTargetId: MutableStateFlow<Int?> = MutableStateFlow(null)\n val replyTargetId = _replyTargetId.asStateFlow()\n\n fun onRefresh() {\n getPost()\n _deletedCommentIds.value = emptySet()\n refreshComments()\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"post_refreshed\"\n )\n }\n\n fun setCommentInput(commentInput: String) {\n _commentInput.value = commentInput\n }\n\n fun setReplyTargetId(commentId: Int) {\n _replyTargetId.value = commentId\n }\n\n fun clearReplyTargetId() {\n _replyTargetId.value = null\n }\n\n private fun getPost() = viewModelScope.launch {\n delay(300) // 화면 전환 애니메이션 버벅임 방지\n\n postRepository.getPost(postId).onSuccess {\n _postDetail.value = it\n }.onFailure {\n _eventChannel.send(PostEvent.ShowSnackbar(\"게시글을 불러올 수 없습니다.\"))\n _eventChannel.send(PostEvent.NavigateBack)\n errorHelper.logError(it)\n }\n }\n\n fun reportPost(reason: String) = viewModelScope.launch {\n postRepository.reportPost(postId, reason)\n .onSuccess { \n _eventChannel.send(PostEvent.ShowSnackbar(\"신고가 접수되었습니다.\"))\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"post_reported\"\n )\n }\n .onFailure { \n _eventChannel.send(PostEvent.ShowSnackbar(\"신고 접수에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun blockUser(providerId: String) = viewModelScope.launch {\n postRepository.blockUser(providerId)\n .onSuccess { \n _eventChannel.send(PostEvent.NavigateBack)\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"user_blocked\"\n )\n }\n .onFailure { \n _eventChannel.send(PostEvent.ShowSnackbar(\"유저 차단에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun deletePost() = viewModelScope.launch {\n postRepository.deletePost(postId = postId)\n .onSuccess { \n _eventChannel.send(PostEvent.NavigateBack)\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"post_deleted\"\n )\n }\n .onFailure { \n _eventChannel.send(PostEvent.ShowSnackbar(\"게시글 삭제에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun toggleEmotion(emotion: Emotion) = viewModelScope.launch {\n postRepository.toggleEmotion(\n postId = postId,\n originEmotionType = _postDetail.value.yourEmotionType,\n emotionType = emotion\n ).onSuccess { isAdded ->\n val current = _postDetail.value\n\n val updatedEmotionCount = current.emotionCount.let { count ->\n var result = count\n\n if (emotion != _postDetail.value.yourEmotionType && _postDetail.value.yourEmotionType != null) {\n result = when (_postDetail.value.yourEmotionType) {\n Emotion.HEARTWARMING -> result.copy(heartWarmingCount = result.heartWarmingCount - 1)\n Emotion.LIKEABLE -> result.copy(likeableCount = result.likeableCount - 1)\n Emotion.TOUCHING -> result.copy(touchingCount = result.touchingCount - 1)\n Emotion.IMPRESSIVE -> result.copy(impressiveCount = result.impressiveCount - 1)\n Emotion.GRATEFUL -> result.copy(gratefulCount = result.gratefulCount - 1)\n else -> result\n }\n }\n\n result = when (emotion) {\n Emotion.HEARTWARMING -> result.copy(heartWarmingCount = result.heartWarmingCount + if (isAdded) 1 else -1)\n Emotion.LIKEABLE -> result.copy(likeableCount = result.likeableCount + if (isAdded) 1 else -1)\n Emotion.TOUCHING -> result.copy(touchingCount = result.touchingCount + if (isAdded) 1 else -1)\n Emotion.IMPRESSIVE -> result.copy(impressiveCount = result.impressiveCount + if (isAdded) 1 else -1)\n Emotion.GRATEFUL -> result.copy(gratefulCount = result.gratefulCount + if (isAdded) 1 else -1)\n }\n\n result\n }\n\n _postDetail.value =\n current.copy(\n yourEmotionType = if (isAdded) emotion else null,\n emotionCount = updatedEmotionCount\n )\n \n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"emotion_toggled\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n private fun refreshComments() = viewModelScope.launch {\n _commentRefreshTrigger.value = !_commentRefreshTrigger.value\n }\n\n fun addComment() = viewModelScope.launch {\n if (_commentInput.value.isEmpty()) {\n _eventChannel.send(PostEvent.ShowSnackbar(\"내용을 입력해주세요.\"))\n return@launch\n }\n\n commentRepository.addComment(postId = postId, content = _commentInput.value)\n .onSuccess {\n _commentInput.value = \"\"\n refreshComments()\n _eventChannel.send(PostEvent.ShowSnackbar(\"댓글이 등록되었습니다.\"))\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"comment_added\"\n )\n }.onFailure {\n _eventChannel.send(PostEvent.ShowSnackbar(\"댓글 등록에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun replyComment(onSuccess: (Int) -> Unit) =\n viewModelScope.launch {\n val parentId = _replyTargetId.value ?: return@launch\n\n if (_commentInput.value.isEmpty()) {\n _eventChannel.send(PostEvent.ShowSnackbar(\"내용을 입력해주세요.\"))\n return@launch\n }\n\n commentRepository.addReplyToComment(\n postId = postId,\n commentId = parentId,\n content = _commentInput.value\n ).onSuccess {\n clearReplyTargetId()\n _commentInput.value = \"\"\n refreshComments()\n onSuccess(parentId)\n _eventChannel.send(PostEvent.ShowSnackbar(\"대댓글이 등록되었습니다.\"))\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"reply_added\"\n )\n }.onFailure {\n _eventChannel.send(PostEvent.ShowSnackbar(\"대댓글 등록에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun deleteComment(commentId: Int) = viewModelScope.launch {\n commentRepository.deleteComment(postId, commentId)\n .onSuccess {\n _eventChannel.send(PostEvent.ShowSnackbar(\"댓글이 삭제되었습니다.\"))\n _deletedCommentIds.value += commentId\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"comment_deleted\"\n )\n }\n .onFailure { \n _eventChannel.send(PostEvent.ShowSnackbar(\"댓글 삭제에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n fun reportComment(commentId: Int, reason: String) = viewModelScope.launch {\n commentRepository.reportComment(commentId, reason)\n .onSuccess { \n _eventChannel.send(PostEvent.ShowSnackbar(\"신고가 접수되었습니다.\"))\n analyticsHelper.trackActionEvent(\n screenName = \"post\",\n actionName = \"comment_reported\"\n )\n }\n .onFailure { \n _eventChannel.send(PostEvent.ShowSnackbar(\"신고 접수에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n sealed class PostEvent {\n data object NavigateBack : PostEvent()\n data class ShowSnackbar(val message: String) : PostEvent()\n\n }\n}"}"}},{"id":"toolu_bdrk_01A9ajin8jcNW2jkFgKyDsgd","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/mypage/src/main/java/com/virtuous/mypage/graph/blocked_user/BlockedUserViewModel.kt", "instructions": "I will add AnalyticsHelper and ErrorHelper to BlockedUserViewModel fo