ics.error.ErrorHelper\nimport com.virtuous.domain.repository.AuthRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass SettingViewModel @Inject constructor(\n private val authRepository: AuthRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<SettingEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n fun logout() = viewModelScope.launch {\n authRepository.logOut()\n _eventChannel.send(SettingEvent.Logout)\n analyticsHelper.trackActionEvent(\n screenName = \"setting\",\n actionName = \"logout_success\"\n )\n }\n\n fun unregisterUser() = viewModelScope.launch {\n authRepository.unregisterUser().onSuccess {\n _eventChannel.send(SettingEvent.NavigateToLogin)\n analyticsHelper.trackActionEvent(\n screenName = \"setting\",\n actionName = \"unregister_user_success\"\n )\n }.onFailure {\n _eventChannel.send(SettingEvent.ShowSnackbar(\"회원 탈퇴에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n sealed class SettingEvent {\n data object Logout : SettingEvent()\n data object NavigateToLogin : SettingEvent()\n data class ShowSnackbar(val message: String) : SettingEvent()\n }\n}"}"}},{"id":"toolu_bdrk_01KvuJQVqNqsc9kjtdn8f4Es","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/mypage/src/main/java/com/virtuous/mypage/graph/swallow/SwallowViewModel.kt", "instructions": "SwallowViewModel에 AnalyticsHelper와 ErrorHelper를 추가하여 사용자 정보 조회에 로깅을 구현합니다.", "code_edit": "package com.virtuous.mypage.graph.swallow\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.user.SwallowLevel\nimport com.virtuous.domain.model.user.UserInfo\nimport com.virtuous.domain.repository.UserRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.SharingStarted\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.distinctUntilChanged\nimport kotlinx.coroutines.flow.map\nimport kotlinx.coroutines.flow.stateIn\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass SwallowViewModel @Inject constructor(\n private val userRepository: UserRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _userInfo = MutableStateFlow(\n UserInfo(\n \"닉네임\", null, 0, 0, 0, 0\n )\n )\n val userInfo = _userInfo.asStateFlow()\n\n val swallowLevel: StateFlow<SwallowLevel> = _userInfo.map {\n SwallowLevel.getLevel(\n it.verifiedPostCount,\n it.completedMissionCount\n )\n }.distinctUntilChanged().stateIn(\n scope = viewModelScope,\n started = SharingStarted.WhileSubscribed(5_000),\n initialValue = SwallowLevel.getLevel(\n _userInfo.value.verifiedPostCount,\n _userInfo.value.completedMissionCount\n )\n )\n\n init {\n getUserInfo()\n }\n\n private fun getUserInfo() = viewModelScope.launch {\n userRepository.getMyUserInfo().onSuccess { userInfo ->\n _userInfo.value = userInfo\n analyticsHelper.trackActionEvent(\n screenName = \"swallow\",\n actionName = \"get_user_info_success\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n}"}"}},{"id":"toolu_bdrk_017NQYLjsDP5skTFVxdVNPju","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/mypage/src/main/java/com/virtuous/mypage/graph/updateprofile/UpdateProfileViewModel.kt", "instructions": "UpdateProfileViewModel에 AnalyticsHelper와 ErrorHelper를 추가하여 프로필 수정과 사용자 정보 조회에 로깅을 구현합니다.", "code_edit": "package com.virtuous.mypage.graph.updateprofile\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.repository.UserRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass UpdateProfileViewModel @Inject constructor(\n private val userRepository: UserRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<UpdateProfileEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n private val _name = MutableStateFlow(\"\")\n val name = _name.asStateFlow()\n\n private val _isNameValid = MutableStateFlow(true)\n val isNameValid = _isNameValid.asStateFlow()\n\n private val _profileImageUrl = MutableStateFlow<String?>(null)\n val profileImage = _profileImageUrl.asStateFlow()\n\n private val _isNameChanged = MutableStateFlow(false)\n val isNameChanged = _isNameChanged.asStateFlow()\n\n private val _isProfileImageChanged = MutableStateFlow(false)\n val isProfileImageChanged = _isProfileImageChanged.asStateFlow()\n\n private var originalName: String = \"\"\n private var originalProfileImageUrl: String? = null\n\n init {\n getMyUserInfo()\n }\n\n private fun getMyUserInfo() = viewModelScope.launch {\n userRepository.loadMyUserInfo().onSuccess { userInfo ->\n originalName = userInfo.name\n originalProfileImageUrl = userInfo.profileImageUrl\n\n setName(userInfo.name)\n setProfileImageUrl(userInfo.profileImageUrl)\n \n analyticsHelper.trackActionEvent(\n screenName = \"update_profile\",\n actionName = \"load_user_info_success\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun setName(name: String) {\n _name.value = name\n validateName()\n _isNameChanged.value = _name.value != originalName\n }\n\n fun setProfileImageUrl(imageUrl: String?) {\n _profileImageUrl.value = imageUrl\n _isProfileImageChanged.value = _profileImageUrl.value != originalProfileImageUrl\n }\n\n private fun validateName() {\n val nicknameRegex = \"^.{$NAME_MIN_LENGTH,$NAME_MAX_LENGTH}$\".toRegex()\n _isNameValid.value = _name.value.trim().matches(nicknameRegex)\n }\n\n fun updateProfile() {\n if (!_isNameChanged.value && !_isProfileImageChanged.value) return\n\n viewModelScope.launch {\n var success = true\n var nameUpdateSuccess = false\n var imageUpdateSuccess = false\n\n if (_isNameChanged.value) {\n val result = userRepository.updateNickname(_name.value)\n if (result.isSuccess) {\n nameUpdateSuccess = true\n } else {\n success = false\n errorHelper.logError(result.exceptionOrNull() ?: Exception(\"Name update failed\"))\n }\n }\n \n if (_isProfileImageChanged.value) {\n val result = userRepository.updateProfileImage(_profileImageUrl.value)\n if (result.isSuccess) {\n imageUpdateSuccess = true\n } else {\n success = false\n errorHelper.logError(result.exceptionOrNull() ?: Exception(\"Profile image update failed\"))\n }\n }\n\n if (success) {\n userRepository.loadMyUserInfo().onSuccess {\n _eventChannel.send(UpdateProfileEvent.NavigateBack)\n \n // 성공한 업데이트 항목별로 로깅\n if (nameUpdateSuccess) {\n analyticsHelper.trackActionEvent(\n screenName = \"update_profile\",\n actionName = \"update_nickname_success\"\n )\n }\n if (imageUpdateSuccess) {\n analyticsHelper.trackActionEvent(\n screenName = \"update_profile\",\n actionName = \"update_profile_image_success\"\n )\n }\n }\n } else {\n _eventChannel.send(UpdateProfileEvent.ShowSnackbar(\"프로필 수정에 실패했습니다.\"))\n }\n }\n }\n\n companion object {\n private const val NAME_MIN_LENGTH = 2\n private const val NAME_MAX_LENGTH = 12\n }\n\n sealed class UpdateProfileEvent {\n data object NavigateBack : UpdateProfileEvent()\n data class ShowSnackbar(val message: String) : UpdateProfileEvent()\n }\n}"}"}},{"id":"toolu_bdrk_012bjbdZ7daA3zAG4skFhp5D","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "feature/mypage/src/main/java/com/virtuous/mypage/graph/blocked_user/BlockedUserViewModel.kt", "instructions": "BlockedUserViewModel에 AnalyticsHelper와 ErrorHelper를 추가하여 차단 사용자 관리에 로깅을 구현합니다.", "code_edit": "package com.virtuous.mypage.graph.blocked_user\n\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport com.virtuous.analytics.AnalyticsHelper\nimport com.virtuous.analytics.error.ErrorHelper\nimport com.virtuous.domain.model.user.BlockedUser\nimport com.virtuous.domain.repository.UserRepository\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.channels.Channel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.flow.receiveAsFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass BlockedUserViewModel @Inject constructor(\n private val userRepository: UserRepository,\n private val analyticsHelper: AnalyticsHelper,\n private val errorHelper: ErrorHelper,\n) : ViewModel() {\n private val _eventChannel = Channel<BlockedUserEvent>()\n val eventChannel = _eventChannel.receiveAsFlow()\n\n private val _blockedUsers: MutableStateFlow<List<BlockedUser>> = MutableStateFlow(emptyList())\n val blockedUsers = _blockedUsers.asStateFlow()\n\n init {\n getBlockedUsers()\n }\n\n private fun getBlockedUsers() = viewModelScope.launch {\n userRepository.getBlockedUsers().onSuccess {\n _blockedUsers.value = it\n analyticsHelper.trackActionEvent(\n screenName = \"blocked_user\",\n actionName = \"get_blocked_users_success\"\n )\n }.onFailure {\n errorHelper.logError(it)\n }\n }\n\n fun unblockUser(providerId: String) = viewModelScope.launch {\n userRepository.unblockUser(providerId).onSuccess {\n _eventChannel.send(BlockedUserEvent.ShowSnackbar(\"차단이 해제되었습니다.\"))\n analyticsHelper.trackActionEvent(\n screenName = \"blocked_user\",\n actionName = \"unblock_user_success\"\n )\n // 차단 해제 후 목록 새로고침\n getBlockedUsers()\n }.onFailure {\n _eventChannel.send(BlockedUserEvent.ShowSnackbar(\"차단 해제에 실패했습니다.\"))\n errorHelper.logError(it)\n }\n }\n\n sealed class BlockedUserEvent {\n data class ShowSnackbar(val message: String) : BlockedUserEvent()\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01QzKHBSZzNBQ2i67mqjGQwi","content":"Error: edit_file failed to execute: HTTP 429 
